WITH lines AS (SELECT id, plan, effective_from, EXPLODE_OUTER(tier_limits) AS val FROM price_tiers) SELECT id, plan, effective_from, val, AVG(val) OVER (PARTITION BY plan) AS plan_avg_val, PERCENT_RANK() OVER (ORDER BY val DESC NULLS LAST) AS val_percent_rank, RANK() OVER (PARTITION BY plan ORDER BY val NULLS FIRST) AS val_rank, MAX(val) OVER (PARTITION BY plan) AS plan_max_val, RANK() OVER (ORDER BY val DESC NULLS LAST) AS val_rank_2 FROM lines
